\begin{ex}%[9H5H2-3]
\immini[thm]{
Cho tam giác ${ABC}$ vuông tại ${A}$ có $AB=28cm$; $AC=45cm$. Khẳng định sai là 

\choice
{  Khoảng cách từ ${O}$ đến dây ${AC}$ bằng ${14}cm$ }
   { Ba điểm ${A, B, C}$ cùng thuộc đường tròn đường kính ${BC}$  }
     { \True  Bán kính của đường ngoại tiếp tam giác ${ABC}$ là ${53}cm$  }
    { Khoảng cách từ ${O}$ đến dây ${AB}$ bằng ${\dfrac{45}{2}}cm$ }
}{
\begin{tikzpicture}
    % Định nghĩa các điểm A, B, C
    \coordinate [label=left:A] (A) at (0, 0);
    \coordinate [label=right:B] (B) at (4, 0);
    \coordinate [label=above:C] (C) at (0, 3);

    % Vẽ tam giác ABC
    \draw[thick] (A) -- (B) -- (C) -- cycle;

    % Đánh dấu các điểm A, B, C
    \fill (A) circle (2pt);
    \fill (B) circle (2pt);
    \fill (C) circle (2pt);

    % Vẽ góc vuông tại A
    \draw (0, 0) rectangle (0.4, 0.4);

    % Tính trung điểm M của AB và N của AC
    \coordinate [label=below:M] (M) at ($(A)!0.5!(B)$);
    \coordinate [label=left:N] (N) at ($(A)!0.5!(C)$);

    % Đánh dấu các điểm M, N
    \fill (M) circle (2pt);
    \fill (N) circle (2pt);

    % Vẽ đường tròn đường kính BC
    \coordinate [label=above:O] (O) at (2,3/2);
    \fill (O) circle (2pt);
    \draw[thick] (O) circle ({5/2});
    \draw[thick] (O) -- (M);
    \draw[thick] (O) -- (N);
\end{tikzpicture}
}
\loigiai{
Áp dụng định lí Pythagore trong $\triangle ABC$ vuông tại $A$: $BC = \sqrt{AB^2 + AC^2} = \sqrt{28^2 + 45^2} = 53$ cm. Bán kính đường tròn ngoại tiếp là $R = \dfrac{BC}{2} = \dfrac{53}{2}$ cm (nên khẳng định $R = 53$ cm là sai).
}\end{ex}

